<script setup lang="ts">
import {computed,ref,reactive,watch,nextTick,onBeforeUnmount} from 'vue'
import {useRoute} from 'vue-router'
import ConstellationCanvas from '../ui/ConstellationCanvas.vue'
import ImmersiveToggle from '../ui/ImmersiveToggle.vue'
import {useAuthStore} from '@/stores/auth'
import {layers,type Layer,type StudyOptions,type StudyReport,type StudyTarget} from '../types'
import EncouragementPanel from '../ui/EncouragementPanel.vue'
import {effects,type EffectId} from '../config/effects'
import {createEncouragementMock,type MockEncouragement} from '../adapters/encouragementMock'
import IdentityProjection from '../ui/IdentityProjection.vue'
import ConstellationWorkbench from '../ui/ConstellationWorkbench.vue'
const workbench=ref<InstanceType<typeof ConstellationWorkbench>>(),workbenchOpen=ref(false)
function feedback(kind:'record'|'node'|'plan',label:string){canvas.value?.feedback(kind);notice.value=label}
const route=useRoute(),canvas=ref<InstanceType<typeof ConstellationCanvas>>(),targets=ref<StudyTarget[]>([]),report=ref<StudyReport>(),failed=ref(false),settings=ref(false),help=ref(true),selected=ref<string>(),closeButton=ref<HTMLButtonElement>()
const props=defineProps<{preset?:Partial<StudyOptions>}>()
const options=reactive<StudyOptions>({members:2,scheme:'A',atmosphere:'dark',motion:true,view:'front',density:.8,layers:{core:true,orbitA:true,orbitB:true,planArc:true,photons:true,relics:true},...props.preset})
watch(()=>route.query,query=>{options.members=query.members==='0'?0:query.members==='1'?1:2;options.scheme=query.scheme==='B'?'B':'A';options.atmosphere=query.atmosphere==='light'?'light':'dark';options.motion=query.motion!=='off';options.view=query.view==='side'?'side':'front';for(const layer of layers)options.layers[layer]=query[layer]!=='off'},{immediate:true})
const layerNames:Record<Layer,string>={core:'生命核心',orbitA:'支持轨道 A',orbitB:'支持轨道 B',planArc:'计划弧线',photons:'空间光子',relics:'纪念迹点'}
const labels:Record<string,string>={core:'生命核心', 'sample-a':'支持者 A · 模拟','sample-b':'支持者 B · 模拟',plan:'计划弧线 · 示意',relic:'纪念晶体 · 示意',invite:'邀请入口 · 示意'}
const focusLabel=computed(()=>selected.value?labels[selected.value]:'')
const composer=ref(false),inbox=ref(false),chosenEffect=ref<EffectId>('glow'),draft=ref(''),sender=ref<'sample-a'|'sample-b'>('sample-a'),previewOnly=ref(false),sending=ref(false),sendError=ref(''),notice=ref(''),records=ref<MockEncouragement[]>([]),mock=createEncouragementMock(localStorage,`nico-local-encouragement-history:${useAuthStore().user?.id??'guest'}`)
const projection=ref<'sample-a'|'sample-b'>(),actor=ref<'quitter'|'sample-a'|'sample-b'>('quitter'),projectionBusy=ref(false),charge=ref<EffectId>()
let projectionSequence=0
const canProjectionSend=computed(()=>Boolean(projection.value&&actor.value===projection.value))
const projectionHistory=computed(()=>actor.value==='quitter'||actor.value===projection.value?records.value.filter(row=>row.senderId===projection.value):[])
const hasModal=computed(()=>Boolean(projection.value||selected.value||composer.value||inbox.value||workbenchOpen.value))
const dismissPlayback=ref(false)
const activeEffect=computed(()=>failed.value||dismissPlayback.value?undefined:report.value?.effect)
const effectLabel=computed(()=>effects.find(effect=>effect.id===activeEffect.value?.id)?.label??'')
const unread=computed(()=>records.value.filter(record=>!record.read).length)
let pending:AbortController|undefined,lastEffect:{id:EffectId;sender:string}|undefined
let previousFocus:HTMLElement|null=null
function select(id:string){if(id.startsWith('memory:mock:')){openInbox(id.slice('memory:mock:'.length));return}if(id==='core'||id==='plan'){canvas.value?.cancelEffect();workbench.value?.open(id);return}if(id==='sample-a'||id==='sample-b'){openProjection(id);return}previousFocus=document.activeElement as HTMLElement;selected.value=id;nextTick(()=>closeButton.value?.focus())}
function openProjection(id:'sample-a'|'sample-b'){previousFocus=document.activeElement as HTMLElement;canvas.value?.cancelEffect();projection.value=id;sendError.value='';charge.value=undefined;void canvas.value?.projectSupporter(id,true)}
async function closeProjection(){const id=projection.value;if(!id)return;projection.value=undefined;charge.value=undefined;await canvas.value?.projectSupporter(id,false);nextTick(()=>previousFocus?.focus())}
async function projectionAction(effect:EffectId,text='',sendRecord=false){
 if(projectionBusy.value||!projection.value)return
 if(sendRecord&&!canProjectionSend.value){sendError.value='仅当前模拟支持者本人可发送';return}
 const id=projection.value,token=++projectionSequence;projectionBusy.value=true;sendError.value=''
 try{
  if(sendRecord){const request=new AbortController();pending=request;await mock.send({senderId:id,effect,text},request.signal);if(request.signal.aborted)return;records.value=mock.list();options.traces=[...(props.preset?.traces??[]),...records.value.map(row=>({id:'mock:'+row.id,kind:'encouragement' as const,date:row.createdAt}))].slice(-100);pending=undefined}
  charge.value=effect
  await new Promise(resolve=>setTimeout(resolve,matchMedia('(prefers-reduced-motion: reduce)').matches?0:650))
  if(token!==projectionSequence)return
  await closeProjection()
  if(token!==projectionSequence)return
  play(effect,id,sendRecord?'已模拟发送':'光效预览')
 }catch(error){if(token===projectionSequence)sendError.value=error instanceof Error?error.message:'模拟发送失败'}
 finally{if(token===projectionSequence)projectionBusy.value=false}
}
watch(actor,()=>{projectionSequence++;pending?.abort();projectionBusy.value=false;void closeProjection();workbench.value?.setSampleRole(actor.value==='quitter'?'quitter':'supporter')})
function close(){selected.value=undefined;nextTick(()=>previousFocus?.focus())}
function openComposer(id:'sample-a'|'sample-b'='sample-a',onlyPreview=true){canvas.value?.cancelEffect();previousFocus=document.activeElement as HTMLElement;sender.value=id;previewOnly.value=onlyPreview;sendError.value='';composer.value=true;inbox.value=false;settings.value=false}
function closeComposer(){pending?.abort();pending=undefined;sending.value=false;composer.value=false;nextTick(()=>previousFocus?.focus())}
function play(id:EffectId,from=sender.value,kind='光效预览'){dismissPlayback.value=false;lastEffect={id,sender:from};notice.value=kind;try{const state=canvas.value?.playEffect(id,from);if(!state||failed.value)notice.value=`${kind} · 当前为二维预览`;else if(state.status==='reduced')notice.value=`${kind} · 动态已减弱`}catch{canvas.value?.cancelEffect();notice.value=`${kind} · 演出暂不可用`;dismissPlayback.value=true}}
function preview(){composer.value=false;play(chosenEffect.value);nextTick(()=>previousFocus?.focus())}
async function send(){if(sending.value)return;if(actor.value!==sender.value){sendError.value='仅当前模拟支持者本人可发送';return;}if(options.members===0||(sender.value==='sample-b'&&options.members<2)){sendError.value='当前没有这个模拟成员';return}const request=new AbortController();pending=request;sending.value=true;sendError.value='';try{const record=await mock.send({senderId:sender.value,effect:chosenEffect.value,text:draft.value},request.signal);if(request.signal.aborted)return;records.value=mock.list();options.traces=[...(props.preset?.traces??[]),...records.value.map(row=>({id:'mock:'+row.id,kind:'encouragement' as const,date:row.createdAt}))].slice(-100);draft.value='';composer.value=false;play(record.effect,record.senderId,'已模拟发送');nextTick(()=>previousFocus?.focus())}catch(error){if(!request.signal.aborted)sendError.value=error instanceof Error?error.message:'模拟发送失败'}finally{if(pending===request){pending=undefined;sending.value=false}}}
records.value=mock.list();options.traces=[...(props.preset?.traces??[]),...records.value.map(row=>({id:'mock:'+row.id,kind:'encouragement' as const,date:row.createdAt}))].slice(-100)
if(props.preset)try{mock.ensureExamples(options.members)}catch{notice.value='示例鼓励无法保存，请检查浏览器存储'}
records.value=mock.list();options.traces=[...(props.preset?.traces??[]),...records.value.map(row=>({id:'mock:'+row.id,kind:'encouragement' as const,date:row.createdAt}))].slice(-100)
const focusedRecord=ref<string>();
function openInbox(id?:string){focusedRecord.value=typeof id==='string'?id:undefined;previousFocus=document.activeElement as HTMLElement;inbox.value=true;settings.value=false;nextTick(()=>closeButton.value?.focus())}
function closeInbox(){inbox.value=false;nextTick(()=>previousFocus?.focus())}
function replay(record:MockEncouragement){mock.markRead(record.id);records.value=mock.list();options.traces=[...(props.preset?.traces??[]),...records.value.map(row=>({id:'mock:'+row.id,kind:'encouragement' as const,date:row.createdAt}))].slice(-100);inbox.value=false;play(record.effect,record.senderId,'模拟收件回放');nextTick(()=>previousFocus?.focus())}
function replayLast(){if(lastEffect)play(lastEffect.id,lastEffect.sender as 'sample-a'|'sample-b','光效重播')}
function cancelEffect(){canvas.value?.cancelEffect();notice.value='已取消演出'}
watch(()=>options.members,()=>{if(projection.value&&(options.members===0||projection.value==='sample-b'&&options.members<2)){projectionSequence++;pending?.abort();projectionBusy.value=false;void closeProjection()}if(composer.value&&(options.members===0||sender.value==='sample-b'&&options.members<2))closeComposer();canvas.value?.cancelEffect()})
onBeforeUnmount(()=>{projectionSequence++;pending?.abort();})
function frame(next:StudyTarget[],stats:StudyReport){targets.value=next;report.value=stats}
function trap(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();inbox.value?closeInbox():close()}else if(event.key==='Tab'){const nodes=Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('button:not([disabled])')),first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}
</script>
<template>
 <main class="constellation-study" :class="{'dark-space':options.atmosphere==='dark'}" :data-study-report="JSON.stringify(report)" :data-members="options.members" :data-scheme="options.scheme" :data-atmosphere="options.atmosphere">
  <header :inert="hasModal ? true : undefined"><a href="#/__hub-preview" aria-label="返回晶体预览">NICØ</a><span>NICØ</span><ImmersiveToggle/><button :aria-expanded="settings" aria-label="打开样板设置" @click="settings=!settings">⋯</button></header>
  <section :inert="hasModal ? true : undefined" class="constellation-stage" aria-label="共生星图空间样板" tabindex="0" @keydown.home.prevent="canvas?.reset()">
   <ConstellationCanvas ref="canvas" :options="options" @frame="frame" @unavailable="failed=true"/>
   <div v-if="!failed" class="scene-targets"><button v-for="target in targets" :key="target.id" :data-target="target.id" :aria-label="target.label" :style="{left:`${target.x}px`,top:`${target.y}px`}" :class="{'core-target':target.id==='core','plan-target':target.id==='plan','star-target':target.id.startsWith('memory:')}" @click="select(target.id)"><span v-if="target.id.startsWith('memory:')" class="record-star" aria-hidden="true">✦</span><span v-else class="target-marker"/></button></div>
   <div v-else class="fallback-sculpture"><div class="fallback-core"/><i class="fallback-orbit a"/><i v-if="options.members!==1" class="fallback-orbit b"/><nav aria-label="无三维图形的样板入口"><button @click="select('core')">生命核心</button><button v-for="index in options.members" :key="index" @click="select(index===1?'sample-a':'sample-b')">支持者 {{index===1?'A':'B'}} · 模拟</button><button @click="select('plan')">计划 · 示意</button></nav></div>
   <button v-if="options.members===0" class="invite" @click="select('invite')" aria-label="邀请支持者，样板入口">＋</button>
   <aside v-if="help" class="interaction-hint">拖动查看 · 点击光核<button aria-label="关闭操作提示" @click="help=false">×</button></aside>
  </section>
  <footer :inert="hasModal ? true : undefined"><span>{{records.length?'点击金色星芒查看鼓励':'暂无鼓励印记'}}</span><div class="footer-actions"><button aria-label="预览鼓励光效" @click="openComposer()">✧</button><button :aria-label="`查看模拟鼓励记录，${unread}条未查看`" @click="openInbox()">◌<sup v-if="unread">{{unread}}</sup></button></div><button aria-label="复位视角" @click="canvas?.reset()">↺</button></footer>
  <section v-if="settings" class="study-settings" aria-label="空间样板设置"><div class="settings-heading">样板设置<button aria-label="关闭设置" @click="settings=false">×</button></div><label>体验身份<select v-model="actor" aria-label="模拟互动身份"><option value="quitter">戒烟者 · 模拟</option><option value="sample-a">知夏 · 模拟</option><option value="sample-b">亦安 · 模拟</option></select></label><label>支持者<select v-model.number="options.members"><option :value="0">0</option><option :value="1">1</option><option :value="2">2</option></select></label><label>氛围<select v-model="options.atmosphere"><option value="light">A · 浅场增强</option><option value="dark">B · 暗场空间</option></select></label><label>动态<input v-model="options.motion" type="checkbox"/></label><label>材质<select v-model="options.scheme"><option value="A">A · 物理透射</option><option value="B">B · 通透优先</option></select></label><label>机位<select v-model="options.view"><option value="front">3/4</option><option value="side">侧面</option></select></label><label v-for="layer in layers" :key="layer"><span>{{layerNames[layer]}}</span><input v-model="options.layers[layer]" type="checkbox"/></label><button aria-label="模拟一次发送失败" @click="mock.failNext()">模拟发送失败</button><label>光子密度<input v-model.number="options.density" type="range" min="0" max="1" step=".05"/></label></section>
  <div v-if="selected" class="study-backdrop" @click.self="close"><section class="study-sheet" role="dialog" aria-modal="true" :aria-label="focusLabel" @keydown="trap"><button ref="closeButton" aria-label="关闭样板详情" @click="close">×</button><h2>{{focusLabel}}</h2><p>{{selected==='core'?'打卡流程在后续阶段接入。':selected==='plan'?'当前展示一个模拟计划：7 个节点，3 个示意亮点。':selected==='invite'?'此处仅预留邀请入口，未创建或邀请任何成员。':selected==='relic'?'可重建的视觉纪念样本，未创建永久成就。':'光核展示模拟支持者；可点击支持光核选择鼓励效果。'}}</p><small>Phase S2 · 模拟预览</small></section></div>
  <IdentityProjection v-if="projection" :sender="projection" :can-send="canProjectionSend" :busy="projectionBusy" :error="sendError" :history="projectionHistory" :charge="charge" @close="closeProjection" @preview="projectionAction($event)" @send="(effect,text)=>projectionAction(effect,text,true)"/>
  <EncouragementPanel v-if="composer" :effect="chosenEffect" :text="draft" :sender-label="previewOnly?'光效样板':labels[sender]!" :preview-only="previewOnly" :sending="sending" :error="sendError" @close="closeComposer" @effect="chosenEffect=$event" @text="draft=$event" @preview="preview" @send="send"/>
  <ConstellationWorkbench ref="workbench" @state="options.coreState=$event" @modal="workbenchOpen=$event" @plan="(nodes,type,status)=>options.plan={nodes,type,status}" @feedback="feedback" @cancel="canvas?.cancelEffect()"/>
  <div v-if="inbox" class="study-backdrop" @click.self="closeInbox"><section class="study-sheet mock-inbox" role="dialog" aria-modal="true" aria-label="模拟鼓励记录" @keydown="trap"><button ref="closeButton" aria-label="关闭模拟记录" @click="closeInbox">×</button><h2>模拟鼓励</h2><p v-if="!records.length">暂无记录</p><ul v-else><li v-for="record in (focusedRecord?records.filter(row=>row.id===focusedRecord):records)" :key="record.id" :data-mock-id="record.id"><button :aria-label="`重播${effects.find(effect=>effect.id===record.effect)?.label}，${record.read?'已查看':'未查看'}`" @click="replay(record)"><span>{{effects.find(effect=>effect.id===record.effect)?.label}}<i v-if="!record.read"/></span><small>{{labels[record.senderId]}} · {{new Date(record.createdAt).toLocaleString('zh-CN')}}</small><p v-if="record.text">{{record.text}}</p></button></li></ul><small>本浏览器保存 · 不同步真实账户</small></section></div>
  <aside v-if="activeEffect?.id&&!hasModal" class="effect-playback" aria-label="光效演出控制" :data-effect-status="activeEffect.status"><span>{{effectLabel}}</span><input v-if="activeEffect.status==='playing'||activeEffect.status==='paused'" type="range" min=".01" max=".99" step=".01" :value="activeEffect.progress" aria-label="光效时间轴" @input="canvas?.seekEffect(Number(($event.target as HTMLInputElement).value))"/><button aria-label="重播当前光效" @click="replayLast">↻</button><button v-if="activeEffect.status==='playing'||activeEffect.status==='paused'" aria-label="取消光效演出" @click="cancelEffect">×</button><button v-else aria-label="关闭演出提示" @click="notice='';dismissPlayback=true;canvas?.cancelEffect()">×</button></aside>
  <p v-if="notice&&!hasModal" class="effect-notice" role="status">{{notice}}</p>
 </main>
</template>
<style scoped>
.constellation-study{min-height:100svh;background:#f4f1e9;color:#475459;font-family:Inter,'Helvetica Neue','PingFang SC','Microsoft YaHei',sans-serif}.constellation-study header{height:72px;padding:0 4.2%;display:flex;align-items:center;justify-content:space-between}.constellation-study header a{font-size:16px;letter-spacing:.34em;color:inherit;text-decoration:none}.constellation-study header>span{position:absolute;left:50%;transform:translateX(-50%);font-size:19px;letter-spacing:.25em}button{color:inherit;font:inherit;cursor:pointer;min-width:44px;min-height:44px;background:transparent;border:0}header button{font-size:25px}.constellation-stage{height:calc(100svh - 110px);min-height:590px;position:relative;overflow:hidden;outline:none}.scene-targets button{position:absolute;transform:translate(-50%,-50%);border-radius:50%;width:52px;height:52px}.scene-targets .core-target{width:150px;height:150px}.scene-targets button:hover .target-marker{position:absolute;inset:6px;border:1px solid #bda47977;border-radius:50%}.scene-targets button:focus-visible{outline:1px solid #9b7d4a;outline-offset:6px}.interaction-hint{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);font-size:10px;letter-spacing:.12em;color:#7c8381;display:flex;align-items:center;white-space:nowrap}.interaction-hint button{font-size:15px}.constellation-study footer{height:38px;padding:0 4.2%;display:flex;align-items:center;justify-content:space-between;font-size:9px;color:#7e8584;letter-spacing:.06em}.constellation-study footer button{font-size:19px}.study-settings{position:absolute;right:4%;top:70px;z-index:5;width:220px;padding:18px 20px;background:#fffdf7ed;border:1px solid #fff;border-radius:15px;box-shadow:0 15px 45px #6a655422;font-size:11px}.settings-heading{display:flex;align-items:center;justify-content:space-between;font-size:13px}.study-settings label{display:flex;justify-content:space-between;align-items:center;min-height:38px;gap:12px}.study-settings select{max-width:145px;border:1px solid #c9c9bc;border-radius:6px;padding:6px;background:transparent;color:inherit;font:inherit}.study-settings input[type=range]{width:110px}.study-backdrop{position:fixed;inset:0;z-index:10;display:grid;place-items:center;background:#f2efe480;backdrop-filter:blur(5px);padding:20px}.study-sheet{width:min(340px,100%);box-sizing:border-box;padding:26px;background:#fffdf6ed;border:1px solid #fff;border-radius:18px;box-shadow:0 24px 70px #626b6322}.study-sheet>button{float:right;margin:-10px -8px 0 0;font-size:22px}.study-sheet h2{font-size:18px;font-weight:400;margin:8px 0 20px}.study-sheet p{font-size:12px;line-height:1.8}.study-sheet small{font-size:9px;color:#84918f}.invite{position:absolute;left:50%;top:78%;transform:translateX(-50%);border:1px solid #b8b7a688;border-radius:50%;font-size:22px}.fallback-sculpture{position:absolute;inset:10% 15% 12%;display:grid;place-items:center}.fallback-core{width:160px;height:160px;border-radius:50%;background:radial-gradient(circle at 30% 20%,white,#b8c7c522,#66797855);border:2px solid #fff;box-shadow:0 18px 70px #85938b22}.fallback-orbit{position:absolute;left:5%;right:5%;top:25%;height:40%;border:2px solid #b9c7c477;border-radius:50%;transform:rotate(-25deg)}.fallback-orbit.b{transform:rotate(45deg)}.fallback-sculpture nav{position:absolute;bottom:0;display:flex;flex-wrap:wrap;justify-content:center;gap:6px}.fallback-sculpture nav button{font-size:11px;border:1px solid #bbbdb144;background:#fff7;border-radius:20px;padding:0 12px}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #9b7d4a;outline-offset:3px}@media(max-width:700px){.constellation-study header{height:62px;padding:0 20px}.constellation-study header a{font-size:11px;letter-spacing:.24em}.constellation-study header>span{font-size:17px}.constellation-stage{height:calc(100svh - 100px);min-height:490px}.scene-targets .core-target{width:100px;height:100px}.interaction-hint{font-size:9px;bottom:12px}.study-settings{right:16px;top:62px}.constellation-study footer{padding:0 20px;font-size:8px}.fallback-sculpture{inset:10% 5% 14%}}
</style>
